$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf();try{$name=text_post('name',100);$email=text_post('email',150);$password=scalar_post('password');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<12)throw new RuntimeException('Use a valid email and a password of at least 12 characters.');transaction(function()use($name,$email,$password){if(run('SELECT COUNT(*) FROM users')->fetchColumn())throw new RuntimeException('Setup is already complete.');run('INSERT INTO users(name,email,password,role,created_at) VALUES(?,?,?,?,?)',[$name,strtolower($email),password_hash($password,PASSWORD_DEFAULT),'Administrator',date('c')]);});flash('Administrator created. Sign in to continue.');header('Location: login.php');exit;}catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Setup failed.';}}
